public abstract record Node { public abstract IReadOnlyList<Node> Children { get; } }
public sealed record Lit(int Value) : Node
{
    public override IReadOnlyList<Node> Children => [];
}
public sealed record Binary(Node Left, string Op, Node Right) : Node
{
    public override IReadOnlyList<Node> Children => [Left, Right];
}

static void Walk(Node n, Action<Node> visit)
{
    visit(n);
    foreach (var c in n.Children) Walk(c, visit);
}
